import assert from "node:assert/strict";
import test from "node:test";
import { readFileSync, mkdtempSync, writeFileSync, rmSync, cpSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { createServer } from "node:http";

// These serialized views come from real TodayApplication writes and readbacks,
// regenerated by PDEX_UI_FIXTURE_DIRECTORY in daily_plan_workflow. Only the
// system IPC boundary is replaced; the full shipped ES module/page/CSS run.
const views = JSON.parse(readFileSync(new URL('./fixtures/plan-time-views.json', import.meta.url), 'utf8'));
async function webKit(view: any, responses: any[], script: string, language = "zh"): Promise<any> {
  const directory = mkdtempSync(join(tmpdir(), 'pdex-plan-dom-'));
  const server=createServer((request,response)=>{
    try { const path=join(directory,request.url==='/'?'index.html':request.url!.slice(1));
      response.setHeader('Content-Type',path.endsWith('.js')?'text/javascript':path.endsWith('.css')?'text/css':'text/html'); response.end(readFileSync(path));
    } catch { response.statusCode=404; response.end(); }
  });
  await new Promise<void>(resolve=>server.listen(0,'127.0.0.1',resolve));
  try {
    cpSync(new URL('../../dist/', import.meta.url), directory, {recursive: true});
    const fixture = `<script>
      window.probeErrors=[]; window.probeCalls=[]; window.probeView=${JSON.stringify(view)};
      window.addEventListener('error', e=>window.probeErrors.push(e.message));
      window.addEventListener('unhandledrejection', e=>window.probeErrors.push(String(e.reason)));
      window.probeResponses=${JSON.stringify(responses)};
      window.__TAURI__={core:{invoke:async(command,args)=>{
        window.probeCalls.push({command,args});
        if(command==='application_identity') return {productName:'Synthetic Dashboard'};
        if(command==='interface_language_preferences') return {interfaceLanguage:${JSON.stringify(language)}};
        if(command==='set_interface_language')return {interfaceLanguage:args.interfaceLanguage};
        if(command==='appearance_preferences') return {accentColor:'forest',backgroundImageState:'none',backgroundImageUrl:null,cleanupWarning:null};
        if(['today_view','daily_view','read_daily_view'].includes(command)) return window.probeView;
        if(command==='today_clock') return {livedDate:window.probeView.date,currentTime:window.probeView.currentTime};
        if(command==='edit_plan_time') { const next=window.probeResponses.shift(); if(!next) throw Error('synthetic uncertain write'); if(next.error) throw Error(next.error); if(next.refreshError)return {savedRevision:next.savedRevision,view:null,refreshError:next.refreshError}; window.probeView=next; return {savedRevision:next.revision,view:next,refreshError:null}; }
        throw Error('Unexpected IPC: '+command);
      }}};
    </script>`;
    const html = readFileSync(join(directory,'index.html'),'utf8').replace('<head>', '<head>'+fixture);
    writeFileSync(join(directory,'index.html'),html);
    writeFileSync(join(directory,'check.js'),`
      const wait = async(test) => { for(let n=0;n<150;n++){ if(test()) return; await new Promise(r=>setTimeout(r,20)); } throw Error('UI timeout: '+JSON.stringify(window.probeErrors)+' '+document.querySelector('#today-status')?.textContent); };
      await wait(()=>document.querySelector('.today-axis-entry-detail button'));
      const planRow=(text='Prepare the project brief')=>[...document.querySelectorAll('.today-axis-entry-detail')].find(row=>row.textContent.includes(text));
      const open = async(text) => { const row=planRow(text); row.open=true; row.querySelector('button').click(); await wait(()=>document.querySelector('dialog.plan-time-editor[open]')); return document.querySelector('dialog.plan-time-editor'); };
      const edits=()=>window.probeCalls.filter(x=>x.command==='edit_plan_time').map(x=>x.args.input);
      ${script}
    `);
    const result=await promisify(execFile)('swift',[new URL('./helpers/rendered-plan-editor.swift',import.meta.url).pathname,
      'http://127.0.0.1:'+(server.address() as any).port+'/',join(directory,'check.js'),'1100'],{encoding:'utf8',timeout:60000});
    return JSON.parse(result.stdout);
  } finally { server.close(); rmSync(directory,{recursive:true,force:true}); }
}

test('clicking an editable Today marker opens the time editor without scrolling to the detail form', {skip:process.platform!=='darwin'},async()=>{
  const result=await webKit(views.loaded,[],`
    const info=document.querySelector('.workspace-information');
    info.scrollTop=0;
    const before=info.scrollTop;
    const marker=document.querySelector('.today-axis-marker[data-plan-id] .today-axis-marker-link');
    if(!marker)throw Error('Editable Today marker missing');
    marker.click();
    await wait(()=>document.querySelector('dialog.plan-time-editor[open]'));
    return JSON.stringify({opened:Boolean(document.querySelector('dialog.plan-time-editor[open]')),before,after:info.scrollTop,errors:window.probeErrors});
  `);
  assert.equal(result.opened,true);
  assert.equal(result.after,result.before,'editing opens as a viewport dialog rather than scrolling to the details row');
  assert.deepEqual(result.errors,[]);
});

test('production fuzzy editor retains approximation and renders the saved readback', {skip:process.platform!=='darwin'},async()=>{
  const result=await webKit(views.loaded,[views.fuzzy],`
    const label=planRow().querySelector('summary').textContent;
    const dialog=await open(); const select=dialog.querySelector('select');
    if(!select) throw Error('Precision choice missing');
    const initial=select.value; const inputs=dialog.querySelectorAll('input[type=time]');
    inputs[0].value='14:00'; dialog.querySelector('form').requestSubmit();
    await wait(()=>edits().length===1 && !document.querySelector('dialog.plan-time-editor'));
    return JSON.stringify({label,initial,input:edits()[0],saved:planRow().querySelector('summary').textContent,errors:window.probeErrors});
  `);
  assert.match(result.label,/午后.*约13:00/);
  assert.equal(result.initial,'approximatePoint');
  assert.equal(result.input.precision,'approximatePoint');
  assert.equal(result.input.startMinute,840); assert.equal(result.input.endMinute,null);
  assert.match(result.saved,/约14:00/); assert.deepEqual(result.errors,[]);
});

test('production precision choices explicitly convert approximate, exact range and exact point without fabricated durations', {skip:process.platform!=='darwin'},async()=>{
  const result=await webKit(views.fuzzy,[views.exact,views.approximate],`
    let dialog=await open(); let select=dialog.querySelector('select'); select.value='exactRange'; select.dispatchEvent(new Event('change'));
    let times=dialog.querySelectorAll('input[type=time]'); times[0].value='15:00'; times[1].value='';
    const endRequired=times[1].required; dialog.querySelector('form').requestSubmit(); const emptyRangeCalls=edits().length;
    times[1].value='16:00'; dialog.querySelector('form').requestSubmit();
    await wait(()=>edits().length===1 && !document.querySelector('dialog.plan-time-editor'));
    const exactLabel=planRow().querySelector('summary').textContent;
    dialog=await open(); select=dialog.querySelector('select'); const exactMode=select.value;
    select.value='exactPoint'; select.dispatchEvent(new Event('change')); const hiddenAtPoint=dialog.querySelectorAll('input[type=time]')[1].disabled;
    select.value='approximatePoint'; select.dispatchEvent(new Event('change')); times=dialog.querySelectorAll('input[type=time]'); times[0].value='16:45';
    dialog.querySelector('form').requestSubmit(); await wait(()=>edits().length===2 && !document.querySelector('dialog.plan-time-editor'));
    return JSON.stringify({endRequired,emptyRangeCalls,exactMode,hiddenAtPoint,exactLabel,inputs:edits(),fuzzyLabel:planRow().querySelector('summary').textContent,errors:window.probeErrors});
  `);
  assert.equal(result.endRequired,true); assert.equal(result.emptyRangeCalls,0);
  assert.equal(result.exactMode,'exactRange'); assert.equal(result.hiddenAtPoint,true);
  assert.match(result.exactLabel,/15:00–16:00/); assert.match(result.fuzzyLabel,/约16:45/);
  assert.deepEqual(result.inputs.map((input:any)=>[input.precision,input.startMinute,input.endMinute]),[['exactRange',900,960],['approximatePoint',1005,null]]);
  assert.deepEqual(result.errors,[]);
});

const inherited=JSON.parse(readFileSync(new URL('./fixtures/inherited-plan-views.json',import.meta.url),'utf8'));
test('production inherited-heading editor uses the captured source and revision while confirmed facts stay unchanged', {skip:process.platform!=='darwin'},async()=>{
  const result=await webKit(inherited.loaded,[inherited.saved],`
    const dialog=await open('Inherited synthetic plan'); const select=dialog.querySelector('select'); const initial=select.value;
    const times=dialog.querySelectorAll('input[type=time]'); const original=[...times].map(input=>input.value);
    times[0].value='10:00'; times[1].value='12:00'; dialog.querySelector('form').requestSubmit();
    await wait(()=>edits().length===1 && !document.querySelector('dialog.plan-time-editor'));
    return JSON.stringify({initial,original,input:edits()[0],saved:planRow('Inherited synthetic plan').querySelector('summary').textContent,errors:window.probeErrors});
  `);
  assert.equal(result.initial,'exactRange'); assert.deepEqual(result.original,['08:00','10:00']);
  assert.equal(result.input.planId,inherited.loaded.timeAxis.currentArrangement[0].planId);
  assert.equal(result.input.expectedRevision,inherited.loaded.revision); assert.equal(result.input.targetBinding,inherited.loaded.targetBinding);
  assert.deepEqual([result.input.startMinute,result.input.endMinute],[600,720]); assert.match(result.saved,/10:00–12:00/); assert.deepEqual(result.errors,[]);
});

test('production uncertain-save editor retains values, disables repeated submission and offers reread', {skip:process.platform!=='darwin'},async()=>{
  const result=await webKit(views.loaded,[],`
    const dialog=await open(); const times=dialog.querySelectorAll('input[type=time]'); times[0].value='14:30';
    dialog.querySelector('form').requestSubmit(); await wait(()=>dialog.querySelector('[role=status]').textContent.includes('未确认'));
    dialog.querySelector('form').dispatchEvent(new Event('submit',{cancelable:true}));
    return JSON.stringify({calls:edits().length,value:times[0].value,disabled:times[0].disabled,precisionDisabled:dialog.querySelector('select').disabled,recheck:[...dialog.querySelectorAll('button')].some(b=>b.textContent==='重新读取核对'&&!b.hidden),label:planRow().querySelector('summary').textContent});
  `);
  assert.equal(result.calls,1); assert.equal(result.value,'14:30'); assert.equal(result.disabled,true); assert.equal(result.precisionDisabled,true);
  assert.equal(result.recheck,true); assert.match(result.label,/午后.*约13:00/);
});

test('production exact-point conversion sends no former range end and survives a fresh page', {skip:process.platform!=='darwin'},async()=>{
  const result=await webKit(views.overnight,[views.point],`
    const dialog=await open(); const select=dialog.querySelector('select'); select.value='exactPoint'; select.dispatchEvent(new Event('change'));
    const times=dialog.querySelectorAll('input[type=time]'); times[0].value='16:30'; dialog.querySelectorAll('input[type=checkbox]')[0].checked=false;
    dialog.querySelector('form').requestSubmit(); await wait(()=>edits().length===1&&!document.querySelector('dialog.plan-time-editor'));
    return JSON.stringify({input:edits()[0],label:planRow().querySelector('summary').textContent});
  `);
  assert.deepEqual([result.input.precision,result.input.startMinute,result.input.endMinute],['exactPoint',990,null]); assert.match(result.label,/16:30/); assert.doesNotMatch(result.label,/约16:30|16:30–/);
  const reopened=await webKit(views.point,[],`
    const dialog=await open(); return JSON.stringify({precision:dialog.querySelector('select').value,start:dialog.querySelector('input[type=time]').value,endDisabled:dialog.querySelectorAll('input[type=time]')[1].disabled});
  `);
  assert.deepEqual(reopened,{precision:'exactPoint',start:'16:30',endDisabled:true});
});


test('production failed manual save rereads unchanged source and requires explicit retry with retained values and fresh revision', {skip:process.platform!=='darwin'},async()=>{
  const result=await webKit(views.loaded,[{error:'synthetic write failure'},views.fuzzy],`
    const dialog=await open(); const times=dialog.querySelectorAll('input[type=time]'); times[0].value='14:00';
    dialog.querySelector('form').requestSubmit(); await wait(()=>dialog.querySelector('[role=status]').textContent.includes('未确认'));
    window.probeView={...window.probeView,revision:'synthetic-authoritative-new-revision'};
    [...dialog.querySelectorAll('button')].find(b=>b.textContent==='重新读取核对').click();
    await wait(()=>!times[0].disabled);
    const afterRead={calls:edits().length,start:times[0].value,precision:dialog.querySelector('select').value};
    dialog.querySelector('form').requestSubmit(); await wait(()=>edits().length===2&&!document.querySelector('dialog.plan-time-editor'));
    return JSON.stringify({afterRead,inputs:edits(),label:planRow().querySelector('summary').textContent,errors:window.probeErrors});
  `);
  assert.deepEqual(result.afterRead,{calls:1,start:'14:00',precision:'approximatePoint'});
  assert.equal(result.inputs[1].expectedRevision,'synthetic-authoritative-new-revision');
  assert.equal(result.inputs[1].planId,result.inputs[0].planId);
  assert.deepEqual(result.inputs.map((input:any)=>[input.precision,input.startMinute,input.endMinute]),[['approximatePoint',840,null],['approximatePoint',840,null]]);
  assert.notEqual(result.inputs[1].operationId,result.inputs[0].operationId);
  assert.match(result.label,/约14:00/); assert.deepEqual(result.errors,[]);
});

test('production failed manual save cannot rebind changed source by matching title or position', {skip:process.platform!=='darwin'},async()=>{
  const result=await webKit(views.loaded,[{error:'synthetic write failure'}],`
    const dialog=await open(); const times=dialog.querySelectorAll('input[type=time]'); times[0].value='14:00';
    dialog.querySelector('form').requestSubmit(); await wait(()=>dialog.querySelector('[role=status]').textContent.includes('未确认'));
    window.probeView=structuredClone(window.probeView); window.probeView.revision='synthetic-changed-source';
    const oldId=edits()[0].planId; window.probeView.timeAxis.currentArrangement.find(entry=>entry.planId===oldId).planId='synthetic-different-raw-source-span';
    [...dialog.querySelectorAll('button')].find(b=>b.textContent==='重新读取核对').click();
    await wait(()=>dialog.querySelector('[role=status]').textContent.includes('来源或修订已改变'));
    dialog.querySelector('form').dispatchEvent(new Event('submit',{cancelable:true}));
    return JSON.stringify({calls:edits().length,start:times[0].value,disabled:times[0].disabled,precisionDisabled:dialog.querySelector('select').disabled,notice:dialog.querySelector('[role=status]').textContent,errors:window.probeErrors});
  `);
  assert.equal(result.calls,1); assert.equal(result.start,'14:00'); assert.equal(result.disabled,true); assert.equal(result.precisionDisabled,true);
  assert.match(result.notice,/重新选择/); assert.deepEqual(result.errors,[]);
});


test('production unchanged untimed plan reread enables explicit timing retry after a failed save', {skip:process.platform!=='darwin'},async()=>{
  const untimed=structuredClone(views.loaded);
  const entry=untimed.timeAxis.currentArrangement.shift();
  entry.startMinute=null; entry.endMinute=null; entry.period='择机'; entry.planPrecision='unlocated';
  untimed.timeAxis.unlocatedCurrentArrangement.push(entry);
  const result=await webKit(untimed,[{error:'synthetic untimed write failure'},views.fuzzy],`
    const dialog=await open(); const times=dialog.querySelectorAll('input[type=time]');
    const original=times[0].value; times[0].value='14:00';
    dialog.querySelector('form').requestSubmit(); await wait(()=>dialog.querySelector('[role=status]').textContent.includes('未确认'));
    [...dialog.querySelectorAll('button')].find(b=>b.textContent==='重新读取核对').click();
    await wait(()=>dialog.querySelector('[role=status]').textContent.includes('明确重试')||dialog.querySelector('[role=status]').textContent.includes('来源或修订已改变'));
    const afterRead={calls:edits().length,start:times[0].value,precision:dialog.querySelector('select').value,disabled:times[0].disabled};
    if(times[0].disabled) return JSON.stringify({original,afterRead,inputs:edits(),errors:window.probeErrors});
    dialog.querySelector('form').requestSubmit(); await wait(()=>edits().length===2&&!document.querySelector('dialog.plan-time-editor'));
    return JSON.stringify({original,afterRead,inputs:edits(),label:planRow().querySelector('summary').textContent,errors:window.probeErrors});
  `);
  assert.equal(result.original,'');
  assert.deepEqual(result.afterRead,{calls:1,start:'14:00',precision:'approximatePoint',disabled:false});
  assert.equal(result.inputs[1].planId,entry.planId); assert.equal(result.inputs[1].expectedRevision,untimed.revision);
  assert.deepEqual([result.inputs[1].startMinute,result.inputs[1].endMinute],[840,null]);
  assert.match(result.label,/约14:00/); assert.deepEqual(result.errors,[]);
});


test('production point editors hide unused End geometry and retain controls through language refresh', {skip:process.platform!=='darwin'},async()=>{
  const result=await webKit(views.point,[],`
    const dialog=await open();const select=dialog.querySelector('select'),times=dialog.querySelectorAll('input[type=time]');
    const endGroup=times[1].closest('div');const snapshot=()=>({hidden:endGroup.hidden,height:endGroup.getBoundingClientRect().height,rects:times[1].getClientRects().length,disabled:times[1].disabled});
    const point=snapshot();select.value='approximatePoint';select.dispatchEvent(new Event('change'));const approximate=snapshot();
    select.value='exactRange';select.dispatchEvent(new Event('change'));const range=snapshot();
    times[0].value='16:35';times[1].value='17:00';document.querySelector('#workspace-language').click();await wait(()=>document.documentElement.lang==='en');
    return JSON.stringify({point,approximate,range,retained:dialog.contains(select)&&dialog.contains(times[0])&&dialog.contains(times[1]),values:[...times].map(time=>time.value),mode:select.value});
  `);
  for(const state of [result.point,result.approximate])assert.deepEqual(state,{hidden:true,height:0,rects:0,disabled:true});
  assert.equal(result.range.hidden,false);assert.ok(result.range.height>0);assert.equal(result.range.disabled,false);
  assert.equal(result.retained,true);assert.deepEqual(result.values,['16:35','17:00']);assert.equal(result.mode,'exactRange');
});

test('production saved readback diagnostic follows English-Chinese-English without replay or losing edit values', {skip:process.platform!=='darwin'},async()=>{
  const diagnostic="文档已保存，但页面刷新失败：Could not read today\'s daily record: Permission denied (os error 13) at /tmp/合成路径；请重新读取核对。";
  const result=await webKit(views.loaded,[{savedRevision:'synthetic-saved-revision',refreshError:diagnostic}],`
    const dialog=await open();const select=dialog.querySelector('select'),time=dialog.querySelector('input[type=time]');time.value='14:30';
    dialog.querySelector('form').requestSubmit();await wait(()=>edits().length===1&&!dialog.querySelector('[role=status]').textContent.includes('结果未确认')&&dialog.querySelector('[role=status]').textContent.length>0);
    const status=dialog.querySelector('[role=status]');const english=status.textContent;
    document.querySelector('#workspace-language').click();await wait(()=>document.documentElement.lang==='zh-CN');const chinese=status.textContent;
    document.querySelector('#workspace-language').click();await wait(()=>document.documentElement.lang==='en');
    return JSON.stringify({english,chinese,again:status.textContent,calls:edits().length,retained:dialog.contains(time)&&dialog.contains(select),value:time.value,disabled:time.disabled,source:planRow().querySelector('summary').textContent,recheck:[...dialog.querySelectorAll('button')].some(button=>button.textContent==='Read record again'&&!button.hidden)});
  `,'en');
  assert.match(result.english,/Document saved, but the display refresh failed:/);
  assert.doesNotMatch(result.english,/文档已保存|页面刷新失败|\{error\}/);
  assert.match(result.chinese,/文档已保存，但页面刷新失败：/);assert.equal(result.again,result.english);
  for(const text of [result.english,result.chinese])assert.ok(text.includes("Could not read today's daily record: Permission denied (os error 13) at /tmp/合成路径"));
  assert.equal(result.calls,1);assert.equal(result.retained,true);assert.equal(result.value,'14:30');assert.equal(result.disabled,true);assert.equal(result.recheck,true);assert.match(result.source,/Around 13:00/);
});
